/* @autogenerated */
package net.civeira.phylax.integrationtest.features.oauth.alt;

import java.util.Optional;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;

import io.quarkus.arc.profile.IfBuildProfile;
import jakarta.annotation.Priority;
import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.inject.Alternative;
import net.civeira.phylax.features.oauth.authentication.domain.AuthenticationData;
import net.civeira.phylax.features.oauth.client.domain.ClientDetails;
import net.civeira.phylax.features.oauth.session.domain.PublicSessionId;
import net.civeira.phylax.features.oauth.session.domain.SessionInfo;
import net.civeira.phylax.features.oauth.session.domain.gateway.SessionStoreGateway;

@IfBuildProfile("test")
@Alternative
@Priority(1)
@ApplicationScoped
public class FixedSessionStore implements SessionStoreGateway {
  private final ConcurrentMap<String, SessionInfo> sessions = new ConcurrentHashMap<>();
  private final ConcurrentMap<String, String> refreshSessions = new ConcurrentHashMap<>();

  @Override
  public Optional<SessionInfo> loadSession(String state) {
    if (state == null || state.isBlank()) {
      return Optional.empty();
    }
    return Optional.ofNullable(sessions.get(state));
  }

  @Override
  public void saveSession(String state, ClientDetails clientDetails, String grant,
      AuthenticationData validationData, String csid) {
    if (validationData.getSid() == null) {
      validationData.setSid(PublicSessionId.random());
    }
    SessionInfo info = SessionInfo.builder().csid(csid).clientId(clientDetails.getClientId())
        .grant(grant).issuer(validationData.getTenant()).userId(validationData.getUsername())
        .withMfa(false).validationData(validationData).build();
    sessions.put(state, info);
  }

  @Override
  public void updateSession(String newState, String oldState) {
    SessionInfo existing = sessions.remove(oldState);
    if (existing != null) {
      sessions.put(newState, existing);
    }
  }

  @Override
  public void updateTokenJtis(String sessionId, String accessJti, String refreshJti) {
    refreshSessions.put(refreshJti, sessionId);
  }

  @Override
  public boolean updateTokenJtisByRefreshJti(String currentRefreshJti, String accessJti,
      String refreshJti) {
    String session = refreshSessions.remove(currentRefreshJti);
    if (session == null) {
      return false;
    }
    refreshSessions.put(refreshJti, session);
    return true;
  }

  @Override
  public boolean isRefreshSessionActive(String refreshJti) {
    String session = refreshSessions.get(refreshJti);
    return session != null && sessions.containsKey(session);
  }

  @Override
  public void deleteSession(String state) {
    sessions.remove(state);
  }

  @Override
  public java.util.Set<String> participatingClients(String state) {
    return loadSession(state).map(si -> java.util.Set.of(si.getClientId()))
        .orElseGet(java.util.Set::of);
  }

  public void clear() {
    sessions.clear();
    refreshSessions.clear();
  }
}
